import { useCallback, useState, useRef, useEffect, memo } from "react";
import {
  ReactFlow,
  Node,
  Background,
  Controls,
  MiniMap,
  ReactFlowProvider,
  applyNodeChanges,
} from "@xyflow/react";
import "@xyflow/react/dist/style.css";

// 简化的自定义节点组件
const CustomNode = memo(
  ({ data }: { data: { text: string; imageUrl?: string } }) => {
    const renderCount = useRef(0);
    useEffect(() => {
      renderCount.current++;
      console.log(
        `节点 ${data.text.slice(0, 10)} 渲染次数: ${renderCount.current}`
      );
    });
    return (
      <div
        style={{
          padding: "10px",
          background: "white",
          borderRadius: "8px",
          minWidth: "150px",
          border: "1px solid #eee",
          fontSize: "14px",
        }}
      >
        <div>{data.text}</div>
        {data.imageUrl && (
          <img
            src={data.imageUrl}
            alt="node"
            style={{
              maxWidth: "100%",
              height: "auto",
              marginTop: "8px",
              borderRadius: "4px",
            }}
          />
        )}
      </div>
    );
  }
);

const FlowPanel = () => {
  const nodeTypes = {
    custom: CustomNode,
  };

  // 在组件内添加渲染计数器
  const renderCount = useRef(0);
  useEffect(() => {
    renderCount.current += 1;
    console.log(`ReactFlow 渲染次数: ${renderCount.current}`);
  });

  const [nodes, setNodes] = useState<Node[]>(
    Array.from({ length: 100 }, (_, i) => ({
      id: `node-${i}`,
      type: "custom",
      position: {
        x: Math.random() * 1000,
        y: Math.random() * 1000,
      },
      data: {
        text: `节点 ${i}`,
        imageUrl: i % 2 === 0 ? "https://picsum.photos/150/100" : undefined,
      },
    }))
  );

  const onNodesChange = useCallback((changes: any) => {
    setNodes((nds) => applyNodeChanges(changes, nds));
  }, []);

  return (
    <ReactFlowProvider>
      <div style={{ width: "100vw", height: "100vh" }}>
        <ReactFlow
          nodes={nodes}
          edges={[]}
          onNodesChange={onNodesChange}
          nodeTypes={nodeTypes}
          fitView
        >
          <Background />
          <Controls />
          <MiniMap />
        </ReactFlow>
      </div>
    </ReactFlowProvider>
  );
};

export default function Test() {
  return <FlowPanel />;
}
