import { Handle, Position, XYPosition } from "@xyflow/react";
import { 
  BaseNode, 
  BaseNodeHeader, 
  BaseNodeHeaderTitle, 
  BaseNodeContent 
} from "./base-node";
import { Badge } from "@/components/ui/badge";
import { Label } from "@/components/ui/label";

interface Props {
  data: {
    position: XYPosition;
    inputFields?: string[];
    outputFields?: string[];
  };
  id: string;
}

const OutputNode = ({ data, id }: Props) => {
  const inputFields = data.inputFields || ["数据", "结果"];
  const outputFields = data.outputFields || ["文件", "报告", "图表"];

  return (
    <BaseNode className="w-64 min-h-[120px]">
      <BaseNodeHeader>
        <BaseNodeHeaderTitle>输出</BaseNodeHeaderTitle>
      </BaseNodeHeader>
      
      <BaseNodeContent className="space-y-3">
        {/* 输入部分 */}
        <div className="space-y-2">
          <Label className="text-sm">输入:</Label>
          <div className="flex flex-wrap gap-1">
            {inputFields.map((field, index) => (
              <Badge
                key={index}
                variant="outline"
                className="text-xs"
              >
                {field}
              </Badge>
            ))}
          </div>
        </div>
        
        {/* 输出部分 */}
        <div className="space-y-2">
          <Label className="text-sm">输出:</Label>
          <div className="flex flex-wrap gap-1">
            {outputFields.map((field, index) => (
              <Badge
                key={index}
                variant="secondary"
                className="text-xs"
              >
                {field}
              </Badge>
            ))}
          </div>
        </div>
      </BaseNodeContent>
      <Handle type="target" position={Position.Left} />

    </BaseNode>
  );
};

export default OutputNode;
