    useEffect(() => {
        // 当PDF面板打开时，提高其z-index
        if (pdfPanelOpen) {
            bringToFront(panel.pdf);
        }
    }, [pdfPanelOpen]);

    useEffect(() => {
        // 当聊天面板打开时，提高其z-index
        if (chatPanelOpen) {
            bringToFront(panel.chat);
        }
    }, [chatPanelOpen]);

