import MarkdownNode from "@/components/flow/node/MarkdownNode";
import type { Node } from "@xyflow/react";
import { NODE_TYPE_MAPS } from "./constants";
import EditableEdge from "@/components/flow/edges/EditableEdge";
import { GroupNode } from "../components/labeled-group-node";
import {
  GenerateTextNodeComponent,
  type GenerateTextNode,
} from "@/components/flow/components/generate-text-node";
import { DropNode } from "@/components/flow/components/drop-node";
import { GenerateTextNodeController } from "@/components/flow/components/generate-text-node-controller";
import { LLMNode, OutputNode } from "../components";

export const nodeTypes = {
  [NODE_TYPE_MAPS.markdown]: MarkdownNode,
  [NODE_TYPE_MAPS.group]: GroupNode,
  [NODE_TYPE_MAPS.generateText]: GenerateTextNodeController,
  [NODE_TYPE_MAPS.drop]: DropNode,
  [NODE_TYPE_MAPS.llm]: LLMNode,
  [NODE_TYPE_MAPS.output]: OutputNode,
};

export type NodeType = keyof typeof nodeTypes;

// TODO: 以下各个 node 的type类型迁移至各自的实现组件最为合适。

export type NodePosition = {
  x: number;
  y: number;
};

export type CreateNodeOptions = {
  data?: Record<string, unknown>;
  position?: NodePosition;
  autoConnect?: boolean; // 是否自动连接到选中的节点
  [key: string]: unknown;
};

export type MarkdownNodeData = {
  content: string;
  title: string;
  color: string;
};

export type GroupNodeData = {
  label: string;
};

export type DropNodeData = {};

export type LLMNodeData = {
  inputFields?: string[];
  outputFields?: string[];
};

export type OutputNodeData = {
  inputFields?: string[];
  outputFields?: string[];
};

export type MarkdownNode = Node<MarkdownNodeData, "markdownNode">;
export type GroupNode = Node<GroupNodeData, "groupNode">;
export type DropNode = Node<DropNodeData, "dropNode">;
export type LLMNode = Node<LLMNodeData, "llmNode">;
export type OutputNode = Node<OutputNodeData, "outputNode">;


export type FlowNode = MarkdownNode | GroupNode | GenerateTextNode | DropNode | LLMNode | OutputNode;

export const edgeTypes = {  
  editableEdge: EditableEdge,
};
