import { useCallback, useState } from "react";
import { Edge, Node } from "@xyflow/react";

export interface ContextMenuType {
  type: "node" | "edge" | "pane" | "selection";
  x?: number;
  y?: number;
  position: {
    top?: number;
    left?: number;
    bottom?: number;
    right?: number;
  };
}

export const useCanvasContext = () => {
  const [contextMenuState, setContextMenuState] =
    useState<ContextMenuType | null>(null);

  // 自适应定位，当底部距离不够时，在上边显示
  const calculateMenuPosition = (
    event: React.MouseEvent,
    containerElement?: HTMLElement
  ) => {
    const MENU_HEIGHT = 580; // 菜单高度
    const MENU_WIDTH = 200; // 菜单宽度
    const calcMenuPosition = (x: number, y: number) => {
      const winH = window.innerHeight;
      const winW = window.innerWidth;
      let top = y;
      let left = x;
      if (y + MENU_HEIGHT > winH) {
        top = Math.max(0, winH - MENU_HEIGHT - 10);
      }
      if (x + MENU_WIDTH > winW) {
        left = Math.max(0, winW - MENU_WIDTH - 10);
      }
      return { top, left };
    };
    const { top, left } = calcMenuPosition(event.clientX, event.clientY);

    return {
      top: top,
      left: left,
    };
  };

  const onNodeContextMenu = useCallback(
    (event: React.MouseEvent, node: Node) => {
      event.preventDefault();

      const position = calculateMenuPosition(
        event,
        event.currentTarget.closest(".react-flow") as HTMLElement
      );

      setContextMenuState({
        type: "node",
        position,
        x: event.clientX,
        y: event.clientY,
      });
    },
    []
  );

  const onEdgeContextMenu = useCallback(
    (event: React.MouseEvent, edge: Edge) => {
      event.preventDefault();

      const position = calculateMenuPosition(
        event,
        event.currentTarget.closest(".react-flow") as HTMLElement
      );

      setContextMenuState({
        type: "edge",
        position,
        x: event.clientX,
        y: event.clientY,
      });
    },
    []
  );

  const onPaneContextMenu = useCallback((event: React.MouseEvent) => {
    event.preventDefault();

    const position = calculateMenuPosition(
      event,
      event.currentTarget as HTMLElement
    );

    setContextMenuState({
      type: "pane",
      position,
    });
  }, []);

  const onSelectionContextMenu = useCallback(
    (event: React.MouseEvent, selection: Node<Record<string, unknown>>[]) => {
      event.preventDefault();
      event?.stopPropagation();

      const position = calculateMenuPosition(
        event,
        event.currentTarget.closest(".react-flow") as HTMLElement
      );

      setContextMenuState({
        type: "selection",
        position,
      });
    },
    []
  );

  const onCloseMenu = () => {
    setContextMenuState(null);
  };

  return {
    contextMenuState,
    setContextMenuState,
    onNodeContextMenu,
    onEdgeContextMenu,
    onPaneContextMenu,
    onSelectionContextMenu,
    onCloseMenu,
  };
};