import { nanoid } from "nanoid";
import { FlowNode, NodePosition } from "./node-types";
import { DEFAULT_COLOR, NODE_TYPE_MAPS } from "./constants";
import { NODE_DEFAULTS } from "@/components/flow/constants/node-defaults";


export const nodeFactory = {
  [NODE_TYPE_MAPS.markdown]: (position: NodePosition) => ({
    id: nanoid(),
    type: NODE_TYPE_MAPS.markdown,
    position,
    width: NODE_DEFAULTS.WIDTH,
    height: NODE_DEFAULTS.MIN_HEIGHT,
    measured: {
      width: NODE_DEFAULTS.WIDTH,
      height: NODE_DEFAULTS.MIN_HEIGHT,
    },
    data: {
      content: "",
      title: "",
      color: DEFAULT_COLOR, // 默认颜色
    },
  }),
  [NODE_TYPE_MAPS.group]: (position: NodePosition) => ({
    id: nanoid(),
    type: NODE_TYPE_MAPS.group,
    position,
    width: NODE_DEFAULTS.WIDTH,
    height: NODE_DEFAULTS.MIN_HEIGHT,
    measured: {
      width: NODE_DEFAULTS.WIDTH,
      height: NODE_DEFAULTS.MIN_HEIGHT,
    },
    data: {
      label: "",
    },
  }),
  [NODE_TYPE_MAPS.generateText]: (position: NodePosition) => ({
    id: nanoid(),
    type: "generate-text" as const,
    position,
    data: {
      status: "idle" as const,
      config: {
        model: "llama-3.1-8b-instant" as const,
      },
      dynamicHandles: {
        tools: [],
      },
    },
  }),
  [NODE_TYPE_MAPS.drop]: (position: NodePosition) => ({
    id: nanoid(),
    type: "dropNode" as const,
    position,
    data: {
      isSource: false, // TODO: 是否是源节点
    },
  }),
  [NODE_TYPE_MAPS.llm]: (position: NodePosition) => ({
    id: nanoid(),
    type: "llmNode" as const,
    position,
    data: {
      inputFields: ["输入"],
      outputFields: ["ai_result"],
    },
  }),
  [NODE_TYPE_MAPS.output]: (position: NodePosition) => ({
    id: nanoid(),
    type: "outputNode" as const,
    position,
    data: {
      inputFields: ["输入"],
      outputFields: ["ai_result"],
    },
  }),
  //   image: () => {},
  //   video: () => {},
  //   audio: () => {},
  //   file: () => {},
  //   text: () => {},
  //   link: () => {},
};

export function createNode(
  nodeType: FlowNode["type"],
  position: NodePosition
): FlowNode {
  if (!nodeType) {
    throw new Error("Node type is required");
  }
  const factory = nodeFactory[nodeType];
  if (!factory) {
    throw new Error(`Unknown node type: ${nodeType}`);
  }
  return factory(position);
}
