import { httpRequest } from '../index'
import { LoginParams, RegisterParams } from './types.d'
export const login = (params: LoginParams) => httpRequest.post('/user/login', params, {
  headers: {
    'Content-Type': 'application/json; charset=utf-8'
  }
})

// 注册
export const register = (params: RegisterParams) => httpRequest.post('/user/reg', {
  ...params
})


export * from './types.d'