const FILTER_LIST = [
  {
    label: "Card Type",
    icon: <Layers size={18} />,
    key: "cardType",
    options: [
      // TODO: 数据获取
      {
        label: "All",
        value: "all",
      },
      {
        label: "Markdown",
        value: NODE_TYPE_MAPS.markdown,
      },
      {
        label: "PDF",
        value: "pdf",
      },
      {
        label: "Group",
        value: NODE_TYPE_MAPS.group,
      },
    ],
  },
  {
    label: "Tag",
    icon: <Tag size={18} />,
    key: "tag",
    options: [
      {
        label: "All",
        value: "all",
      },
      // 数据获取
    ],
  },
];

// 卡片数据类型
interface CardItemData {
  id: string;
  title: string;
  content: string;
  type: "markdown" | "pdf" | "groupNode";
  color?: string;
  x?: number;
  y?: number;
  width?: number;
  height?: number;
}

// 类型对应的 badge 样式和文本
const TYPE_CONFIG = {
  markdownNode: {
    label: "Markdown",
    variant: "default" as const,
  },
  pdf: {
    label: "PDF",
    variant: "secondary" as const,
  },
  groupNode: {
    label: "Group",
    variant: "outline" as const,
  },
};

interface CardItemProps {
  data: CardItemData;
  onClick?: (id: string) => void;
}

const CardItem = ({ data, onClick }: CardItemProps) => {
  const typeConfig = TYPE_CONFIG[data.type as keyof typeof TYPE_CONFIG];

  return (
    <Card
      className="relative aspect-square cursor-pointer hover:shadow-lg hover:scale-[1.02] transition-all duration-200 border-border/50 hover:border-border group"
      onClick={() => onClick?.(data.id)}
    >
      <CardHeader className="pb-2 px-4 pt-4">
        <CardTitle className="text-sm font-semibold line-clamp-2 leading-tight group-hover:text-primary transition-colors">
          {data.title}
        </CardTitle>
      </CardHeader>
      <CardContent className="px-4 pb-4 pt-2 h-full flex flex-col justify-between">
        <p className="text-xs text-muted-foreground line-clamp-4 leading-relaxed flex-1">
          {data.content}
        </p>
        {/* Badge 在右下角 */}
        <div className="flex justify-end mt-3">
          <Badge
            // variant={typeConfig.variant}
            className="text-xs px-2 py-1 font-medium"
          >
            {typeConfig?.label || "Unknown"}
          </Badge>
        </div>
      </CardContent>
    </Card>
  );
};

const CardListFilter = ({ onChange }: { onChange: (filters: any) => void }) => {
  const [filters, setFilters] = useState({
    cardType: "all",
    tag: "all",
  });
  const [search, setSearch] = useState("");

  const tagGroups = useTagGroups();
  const { loadTagGroups, isLoading } = useTagStore();

  useEffect(() => {
    loadTagGroups();
  }, [loadTagGroups]);

  const handleFilterChange = (filterKey: string, value: string) => {
    setFilters((prev) => ({
      ...prev,
      [filterKey]: value,
    }));
    // TODO: 在这里触发筛选逻辑
    console.log("Filter changed:", filterKey, value);
    onChange({
      ...filters,
      [filterKey]: value,
    });
  };

  // 动态生成标签选项
  const tagOptions = [
    { label: "All", value: "all" },
    ...tagGroups.flatMap((group) =>
      group.tags.map((tag) => ({
        label: `${group.title}: ${tag.name}`,
        value: tag.id,
      }))
    ),
  ];

  // 更新FILTER_LIST中的标签选项
  const dynamicFilterList = FILTER_LIST.map((item) => {
    if (item.key === "tag") {
      return { ...item, options: tagOptions };
    }
    return item;
  });
  const onSearch = (e: React.ChangeEvent<HTMLInputElement>) => {
    onChange({
      ...filters,
      search: e.currentTarget.value,
    });
  };

  return (
    <div className="bg-card rounded-lg">
      <h2 className="text-lg my-4 font-semibold text-foreground flex items-center gap-2">
        <Layers size={24} />
        Card List
      </h2>
      <div className="flex flex-col sm:flex-row gap-4 items-start sm:items-end">
        <div className="flex flex-col sm:flex-row gap-4 flex-1">
          {dynamicFilterList.map((item) => (
            <div key={item.label} className="space-y-2 min-w-[160px]">
              <label className="flex gap-2 items-center text-sm font-medium text-muted-foreground">
                {item.icon} {item.label}
              </label>
              <Select
                value={filters[item.key as keyof typeof filters]}
                onValueChange={(value) => handleFilterChange(item.key, value)}
              >
                <SelectTrigger className="w-full" size="sm">
                  <SelectValue placeholder="Select an option" />
                </SelectTrigger>
                <SelectContent>
                  {item.options.map((option) => (
                    <SelectItem key={option.value} value={option.value}>
                      {option.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          ))}
          <div className="flex items-center gap-2 flex-col">
            <label className="text-sm font-medium text-muted-foreground invisible">
              关键词搜索
            </label>
            <div className="relative w-full">
              <Search
                className="absolute left-2 top-1/2 transform -translate-y-1/2 text-muted-foreground"
                size={16}
              />
              <Input
                onChange={onSearch}
                className="w-full h-8 pl-8"
                placeholder="Search"
              />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

const CardList = ({
  onClose,
  zIndex,
}: {
  onClose: () => void;
  zIndex: number;
}) => {
  const [list, setList] = useState<CardItemData[]>([]);
  const [loading, setLoading] = useState(true);
  const [nodes, setNodes] = useState<CardItemData[]>([]);
  const [pdfs, setPdfs] = useState<any[]>([]);
  const pdfStoreData = usePdfStore((state) => state.pdfs);
  const [filters, setFilters] = useState({
    cardType: "all",
    tag: "all",
    search: "",
  });

  const fetchNodes = async () => {
    try {
      const allCanvas = await canvasService.list({ wid: "" });
      const nodes = reduce(
        allCanvas.list,
        (prev: any, curr: any) => {
          const currentCanvas = JSON.parse(curr.content);
          return [...prev, ...currentCanvas.nodes];
        },
        []
      ).map((node: any) => {
        return {
          id: node.id,
          title: node.data.title,
          content: node.data.content,
          color: node.data.color,
          x: node.x,
          y: node.y,
          width: node.width,
          height: node.height,
          ...node,
        };
      });

      console.log("canvas", { nodes });
      setNodes(nodes || []);

      // 调试：查看节点数据
      console.log("获取到的节点数量:", nodes?.length || 0);
      if (nodes && nodes.length > 0) {
        console.log("节点示例:", nodes.slice(0, 2));
      }
    } catch (error) {
      console.error("获取节点列表失败：", error);
      setNodes([]);
    } finally {
      setLoading(false);
    }
  };
  const processPdfData = () => {
    const pdfArray = [];

    for (const [aid, pdfData] of pdfStoreData) {
      // 提取所有高亮文本
      const highlightTexts =
        pdfData.highlights
          ?.map((highlight: CustomHighlight) => highlight.content?.text || "")
          .filter((text) => text.trim() !== "")
          .join(" ") || "";

      pdfArray.push({
        aid,
        filename: pdfData.filename,
        url: pdfData.url,
        highlightTexts,
        highlightCount: pdfData.highlights?.length || 0,
      });
    }

    setPdfs(pdfArray);

    console.log("获取到的PDF数量:", pdfArray.length);
    if (pdfArray.length > 0) {
      console.log("PDF示例:", pdfArray.slice(0, 2));
    }
  };

  useEffect(() => {
    processPdfData();
  }, [pdfStoreData]);

  const data_list = useMemo(() => {
    return [
      ...nodes.map((node: any) => ({ ...node, ...node.data })),
      ...pdfs.map((pdf) => ({
        ...pdf,
        id: pdf.aid,
        title: pdf.filename,
        content: pdf.highlightTexts,
        type: "PDF",
      })),
    ].filter((item) => {
      let isMatch = true;
      if (filters.cardType !== "all") {
        isMatch = item.type === filters.cardType;
      }
      if (filters.tag !== "all") {
        isMatch = includes(item.tags, filters.tag)
      }
      if (filters.search) {
        console.log("filters.search", filters.search);
        console.log("item.title", item.title);
        console.log("item.content", item.content);
        isMatch =
          includes(toLower(item.title), toLower(filters.search)) ||
          includes(toLower(item.content), toLower(filters.search));
      }
      if(isMatch){

      }
      // 过滤掉不支持的类型
      return isMatch;
    });
  }, [nodes, pdfs, filters]);

  useEffect(() => {
    setLoading(true);
    Promise.all([fetchNodes(), processPdfData()]).finally(() => {
      setLoading(false);
    });
  }, []);

  const handleCardClick = (id: string) => {
    console.log("Card clicked:", id);
    // TODO: 处理卡片点击事件
  };

  return (
    <div
      className=" absolute left-0 right-0 top-0 bottom-0 z-[1001] bg-white p-6"
      style={{ zIndex }}
    >
      <div className="flex flex-col gap-6 h-full">
        {/* 筛选器顶部区域 */}
        <div className="flex-shrink-0">
          <CardListFilter onChange={setFilters} />
          {/* {data_list.length} */}
        </div>
        {/* 分割线 */}
        <div className="h-px bg-border" />
        {/* 卡片网格区域 */}
        <div className="flex-1 overflow-auto py-2">
          {loading ? (
            <div className="text-center py-12">
              <p className="text-muted-foreground">加载中...</p>
            </div>
          ) : (
            <>
              <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 2xl:grid-cols-6 gap-4">
                {data_list.map((item) => (
                  <CardItem
                    key={item.id}
                    data={item}
                    onClick={handleCardClick}
                  />
                ))}
              </div>

              {data_list.length === 0 && (
                <div className="text-center py-12">
                  <p className="text-muted-foreground">暂无内容</p>
                </div>
              )}
            </>
          )}
        </div>
      </div>
    </div>
  );
};

export default CardList;
