
export const getRandomColor = () => {
  const PRESET_COLORS = [
    "#5B9BD5", // 清新蓝
    "#70AD47", // 自然绿
    "#ED7D31", // 活力橙
    "#A065D5", // 梦幻紫
    "#4BACC6", // 湖水蓝
    "#E4A57B", // 暖珊瑚
    "#F7C697", // 柔和杏
  ];
  const randomIndex = Math.floor(Math.random() * PRESET_COLORS.length);
  return PRESET_COLORS[randomIndex];
};
