import {usePdfStore} from "@/store/pdf-store.ts";
import {Tabs} from "antd";
import {useCallback} from "react";

export const Main = () => {
    const {tabItems, activeAid, setActiveAid} = usePdfStore((state) => ({
        tabItems: state.tabItems,
        activeAid: state.activeAid,
        setActiveAid: state.setActiveAid,
    }))
    const onEdit = useCallback((key: React.MouseEvent | React.KeyboardEvent | string) => {
        const state = usePdfStore.getState()
        const tabItems = state.tabItems || []
        const newTabItems = tabItems.filter((item) => item.key !== key)
        state.setTabItems(newTabItems)
        if (state.activeAid === key) {
            const index = tabItems.findIndex((item) => item.key === key)
            if (newTabItems.length > 0) {
                setActiveAid(newTabItems[index === tabItems.length - 1 ? index - 1 : index].key)
            } else {
                setActiveAid("")
            }
        }
    }, [setActiveAid])
    
    return (
        <PdfMainLayout>
            <div className="h-full flex flex-col flex-1 min-w-0 pdf-main">
                <Tabs
                    hideAdd
                    className="flex-grow min-h-0"
                    type="editable-card"
                    activeKey={activeAid}
                    items={tabItems}
                    tabBarGutter={0}
                    onChange={setActiveAid}
                    onEdit={onEdit}
                />
            </div>
        </PdfMainLayout>
        
    )
}

const PdfMainLayout = (props: {children: React.ReactNode}) => {
    return (
        <div
            className="flex-1 overflow-hidden"
        >
            <div className="h-[100%] w-[100%] border-box overflow-hidden">
                {props.children}
            </div>
        </div>
    )
}