/**
 * 生成唯一ID
 * 使用时间戳+随机数的方式生成唯一ID
 */
export function generateId(): string {
    return crypto.randomUUID();
}

/**
 * 批量生成ID
 * @param num 需要生成的ID数量
 */
export function generateIds(num: number): string[] {
    const ids: string[] = [];
    for (let i = 0; i < num; i++) {
        ids.push(generateId());
    }
    return ids;
} 