import { useCallback, useState, MouseEventHandler } from "react";
import { 
  useReactFlow, 
  type Node, 
  type Edge,
  OnConnectStart,
  IsValidConnection,
  getOutgoers
} from "@xyflow/react";
import { getRectRelation } from "../lib/rect";
import { NODE_TYPE_MAPS } from "../lib/constants";
import { NodeType, CreateNodeOptions } from "../lib/node-types";

interface UseCanvasInteractionsProps {
  setNodes: React.Dispatch<React.SetStateAction<Node[]>>;
  setEdges: React.Dispatch<React.SetStateAction<Edge[]>>;
  save: () => void;
  addNode: (type: NodeType, options?: CreateNodeOptions) => string;
}

// 验证连接源和目标的合法性
const isValidSourceTarget = (source: Node, target: Node) => {
  if (source.type === "video" || source.type === "drop") {
    return false;
  }

  if (target.type === "audio" && source.type !== "text") {
    return false;
  }

  if (target.type === "file") {
    return false;
  }

  return true;
};

export const useCanvasInteractions = (props: UseCanvasInteractionsProps) => {
  const { setNodes, setEdges, save, addNode } = props;
  
  const { 
    getInternalNode, 
    screenToFlowPosition,
    getNodes,
    getEdges
  } = useReactFlow();

  // 拖拽状态管理
  const [dropParentId, setDropParentId] = useState<string | undefined>(undefined);

  // 节点拖拽处理
  const onNodeDrag = useCallback(
    (event: React.MouseEvent, draggedNode: Node) => {
      const internalNode = getInternalNode(draggedNode.id);
      const abs = internalNode?.internals.positionAbsolute;

      setNodes((currentNodes) => {
        let newParentId = undefined;
        const newNodes = currentNodes.map((node: Node) => {
          if (node.id === draggedNode.id) return node;
          if (node.type !== NODE_TYPE_MAPS.group) return node;
          if (draggedNode.type === NODE_TYPE_MAPS.group) return node;

          const relation = getRectRelation(
            {
              x: abs?.x ?? 0,
              y: abs?.y ?? 0,
              width: draggedNode.measured?.width ?? 0,
              height: draggedNode.measured?.height ?? 0,
            },
            {
              x: node.position.x,
              y: node.position.y,
              width: node.measured?.width ?? 0,
              height: node.measured?.height ?? 0,
            }
          );

          if (relation === "contain") {
            newParentId = node.id;
          }

          return {
            ...node,
            className:
              relation === "contain"
                ? "highlight_contain"
                : relation === "overlap"
                ? "highlight_overlap"
                : "",
          };
        });
        
        if (newParentId) {
          setDropParentId(newParentId);
        } else {
          setDropParentId(undefined);
        }
        
        return newNodes;
      });
    },
    [setNodes, getInternalNode]
  );

  // 更新父节点ID的辅助函数
  const updateParentId = useCallback(
    (nodeId: string, parentId: string) => {
      const internalNode = getInternalNode(nodeId);
      const abs = internalNode?.internals.positionAbsolute;
      const parentNode = getInternalNode(parentId);
      const parentAbs = parentNode?.internals.positionAbsolute;
      return {
        x: (abs?.x ?? 0) - (parentAbs?.x ?? 0),
        y: (abs?.y ?? 0) - (parentAbs?.y ?? 0),
      };
    },
    [getInternalNode]
  );

  // 节点拖拽结束处理
  const onNodeDragStop = useCallback(
    (event: React.MouseEvent, draggedNode: Node) => {
      setNodes((currentNodes) =>
        currentNodes.map((node) => {
          if (node.id === draggedNode.id && draggedNode.type !== NODE_TYPE_MAPS.group) {
            if (dropParentId) {
              return {
                ...node,
                position: updateParentId(node.id, dropParentId),
                parentId: dropParentId,
              };
            } else {
              const internalNode = getInternalNode(node.id);
              const abs = internalNode?.internals.positionAbsolute;

              return {
                ...node,
                position: {
                  x: abs?.x ?? 0,
                  y: abs?.y ?? 0,
                },
                parentId: undefined,
              };
            }
          }
          return {
            ...node,
            className: "",
          };
        })
      );
      setDropParentId(undefined);
      save();
    },
    [setNodes, getInternalNode, updateParentId, dropParentId, save]
  );

  // 连接开始处理
  const handleConnectStart = useCallback<OnConnectStart>(() => {
    // 删除拖拽时的临时节点
    setNodes((nds: Node[]) => nds.filter((n: Node) => n.type !== "drop"));
    setEdges((eds: Edge[]) => eds.filter((e: Edge) => e.type !== "temporary"));
    save();
  }, [setNodes, setEdges, save]);

  // 验证连接合法性
  const isValidConnection = useCallback<IsValidConnection>(
    (connection) => {
      const nodes = getNodes();
      const edges = getEdges();
      const target = nodes.find((node) => node.id === connection.target);

      if (connection.source) {
        const source = nodes.find((node) => node.id === connection.source);

        if (!source || !target) {
          return false;
        }

        const valid = isValidSourceTarget(source, target);

        if (!valid) {
          return false;
        }
      }

      // 防止循环连接
      const hasCycle = (node: Node, visited = new Set<string>()) => {
        if (visited.has(node.id)) {
          return false;
        }

        visited.add(node.id);

        for (const outgoer of getOutgoers(node, nodes, edges)) {
          if (outgoer.id === connection.source || hasCycle(outgoer, visited)) {
            return true;
          }
        }
      };

      if (!target || target.id === connection.source) {
        return false;
      }

      return !hasCycle(target);
    },
    [getNodes, getEdges]
  );

  // 双击创建markdown节点
  const createMarkdownNode = useCallback<MouseEventHandler<HTMLDivElement>>(
    (event) => {
      if (!(event.target instanceof HTMLElement)) {
        return;
      }

      // 检查是否点击在空白画板上
      if (!event.target.classList.contains("react-flow__pane")) {
        return;
      }

      const { x, y } = screenToFlowPosition({
        x: event.clientX,
        y: event.clientY,
      });
      
      addNode(NODE_TYPE_MAPS.markdown, {
        position: { x, y },
      });
    },
    [addNode, screenToFlowPosition]
  );

  // 拖拽Drop处理
  const handleDrop = useCallback<MouseEventHandler<HTMLDivElement>>((event) => {
    const { x, y } = screenToFlowPosition({
      x: event.clientX,
      y: event.clientY,
    });
    addNode(NODE_TYPE_MAPS.drop, {
      position: { x, y },
    });
  }, [addNode, screenToFlowPosition]);

  // 右键菜单处理
  const handleContextMenu = useCallback((event: MouseEvent) => {
    if (
      !(event.target instanceof HTMLElement) ||
      !event.target.classList.contains("react-flow__pane")
    ) {
      event.preventDefault();
    }
  }, []);

  // 连接线样式
  const connectionLineStyle = {
    strokeWidth: 2,
    stroke: '#999',
  };

  return {
    // 拖拽相关
    onNodeDrag,
    onNodeDragStop,
    
    // 连接相关
    handleConnectStart,
    isValidConnection,
    connectionLineStyle,
    
    // 交互事件
    createMarkdownNode,
    handleDrop,
    handleContextMenu,
  };
};